-- Preserve existing source provenance separately from room records.
CREATE TABLE IF NOT EXISTS room_type_source_metadata (
 tenant_id TEXT NOT NULL,room_type_id TEXT NOT NULL,source_system TEXT NOT NULL,
 cms_locale_id TEXT,source_created_on TEXT,source_last_updated TEXT,source_last_published TEXT,
 source_is_archived INTEGER CHECK(source_is_archived IN (0,1)),source_is_draft INTEGER CHECK(source_is_draft IN (0,1)),
 PRIMARY KEY(tenant_id,room_type_id,source_system),FOREIGN KEY(tenant_id,room_type_id) REFERENCES room_types(tenant_id,id));
INSERT OR IGNORE INTO room_type_source_metadata(tenant_id,room_type_id,source_system,cms_locale_id,source_created_on,source_last_updated,source_last_published,source_is_archived,source_is_draft) SELECT tenant_id,id,'webflow_cms','6abc810fd801e90511049ada','2026-09-30T18:12:00.482Z','2026-11-03T04:17:20.112Z','2026-11-03T04:17:20.112Z',0,0 FROM room_types WHERE id='6abd50f0e0589519e89a7f10';
